from ledgerly.models import Payment

T0 = datetime(2026, 10, 1, tzinfo=timezone.utc)
def p(amt="2000.00"):
    return Payment("pay_1","inv_1",Decimal(amt),status="captured",created_at=T0,captured_at=T0)

# at threshold: no approval needed
x=p(); outage_refund(x, Decimal("1000.00"), T0); print("at threshold", x.refunded_amount)
